import{_ as o,l as i,o as t,c as m,v as e,p as n,x as l,d as s,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"麦克斯韦方程到波动方程","description":"","frontmatter":{"title":"麦克斯韦方程到波动方程","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/maxwell-to-wave.md","filePath":"litho/maxwell-to-wave.md","lastUpdated":1789023840000}'),d={name:"litho/maxwell-to-wave.md"};function f(E,a,b,c,u,_){const r=i("Mermaid");return t(),m("div",null,[a[1]||(a[1]=e('<h1 id="麦克斯韦方程到波动方程" tabindex="-1">麦克斯韦方程到波动方程 <a class="header-anchor" href="#麦克斯韦方程到波动方程" aria-label="Permalink to &quot;麦克斯韦方程到波动方程&quot;">​</a></h1><div class="epigraph"><p>无源、均匀介质里，电场与磁场各自满足同一波动方程；波速由介电常数与磁导率决定，不是另给的经验常数。</p><footer>—— 据 Jackson, Classical Electrodynamics 对 Maxwell 方程线性化与波动解的整理</footer></div><p>本课是光刻栏第一课。后课默认已经读完本课：均匀介质里的光是满足麦克斯韦方程的电磁扰动，以有限速度传播，时谐场满足亥姆霍兹方程。本课不从「什么是光刻机」起笔，也不从分辨总问题起笔。投影、掩模、抗蚀剂最终都落在场如何传播；先把场方程收成波动方程，折射率、平面波、界面与透镜才有根。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口语里常说「193 nm 光」「EUV 13.5 nm」，但波长、相位沿路径如何累积，都必须从场方程读出来。若一开始就把问题写成「怎样印出细线」，\\(\\lambda\\) 还没有在方程里对应任何量，后面的孔径与干涉会变成无根符号。缺口因此不是产线参数，而是：从麦克斯韦方程出发，说明光在均匀介质里以波的形式走，且波速由材料常数决定。</p><p>真空中 \\(c=1/\\sqrt{\\mu_0\\varepsilon_0}\\)。进入线性介质，同样形式，只把 \\(\\varepsilon\\)、\\(\\mu\\) 换成介质值。后课把 \\(n=\\sqrt{\\varepsilon_r\\mu_r}\\) 写成折射率，并在 <a href="/litho/em-wave-index">单色波、折射率与光程</a> 里把光程钉死；本课先保证波动方程本身成立。光学这十三课只铺到 <a href="/litho/scalar-diffraction-bound">标量衍射的适用边界</a>，不把成像主线提前讲完。</p><h3 id="不是从分辨公式起笔" tabindex="-1">不是从分辨公式起笔 <a class="header-anchor" href="#不是从分辨公式起笔" aria-label="Permalink to &quot;不是从分辨公式起笔&quot;">​</a></h3><p>\\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\) 是成像主线在光瞳与部分相干都就绪之后的产线判据。本课连 \\(\\lambda\\) 在波动方程里对应什么都还没固定，不能提前写判据，也不能把光刻机当黑箱来介绍。</p><p><span class="marginnote">本课用 SI 制。\\(\\varepsilon\\)、\\(\\mu\\) 为真空值乘相对值。光学频段通常 \\(\\mu_r\\approx 1\\)，于是 \\(n\\approx\\sqrt{\\varepsilon_r}\\)。吸收与复介电常数本课不引入。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无源区（\\(\\rho=0\\)，\\(\\mathbf{J}=0\\)）的麦克斯韦方程：</p> \\[\\nabla\\cdot\\mathbf{D}=0,\\quad \\nabla\\cdot\\mathbf{B}=0,\\quad \\nabla\\times\\mathbf{E}=-\\frac{\\partial\\mathbf{B}}{\\partial t},\\quad \\nabla\\times\\mathbf{H}=\\frac{\\partial\\mathbf{D}}{\\partial t}. \\]<p>线性、均匀、各向同性：\\(\\mathbf{D}=\\varepsilon\\mathbf{E}\\)，\\(\\mathbf{B}=\\mu\\mathbf{H}\\)。对 \\(\\mathbf{E}\\) 取旋度，用恒等式 \\(\\nabla\\times(\\nabla\\times\\mathbf{E})=\\nabla(\\nabla\\cdot\\mathbf{E})-\\nabla^2\\mathbf{E}\\) 与无源条件 \\(\\nabla\\cdot\\mathbf{E}=0\\)，得</p> \\[\\nabla^2\\mathbf{E}-\\mu\\varepsilon\\,\\frac{\\partial^2\\mathbf{E}}{\\partial t^2}=0. \\]<p>\\(\\mathbf{H}\\) 满足同样形式。波速 \\(v=1/\\sqrt{\\mu\\varepsilon}\\)；真空中 \\(v=c\\)。时谐约定 \\(\\mathbf{E}(\\mathbf{r},t)=\\mathrm{Re}\\{\\mathbf{E}(\\mathbf{r})e^{-i\\omega t}\\}\\) 代入，得亥姆霍兹方程 \\(\\nabla^2\\mathbf{E}+k^2\\mathbf{E}=0\\)，\\(k=\\omega\\sqrt{\\mu\\varepsilon}=\\omega/v\\)。后课平面波就是这个方程在无限均匀介质里的特解。</p>',15)),(t(),n(p,null,{default:l(()=>[h(r,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAX%5B%22%E9%BA%A6%E5%85%8B%E6%96%AF%E9%9F%A6%E6%96%B9%E7%A8%8B%22%5D%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%E5%9D%87%E5%8C%80%E6%97%A0%E6%BA%90%E4%BB%8B%E8%B4%A8%22%5D%0A%20%20LIN%20--%3E%20WAVE%5B%22%E6%B3%A2%E5%8A%A8%E6%96%B9%E7%A8%8B%22%5D%0A%20%20WAVE%20--%3E%20HH%5B%22%E6%97%B6%E8%B0%90%20%E2%86%92%20%E4%BA%A5%E5%A7%86%E9%9C%8D%E5%85%B9%22%5D%0A%20%20HH%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%B9%B3%E9%9D%A2%E6%B3%A2%E4%B8%8E%20k%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>波动方程说明：扰动不是瞬时传到远处，而是以有限速度 \\(v\\) 传播。光源、投影物镜里的玻璃、浸没液体，在波长尺度上常可先当成均匀块，本课方程在这些块的内部成立。界面上场不连续，切向 \\(\\mathbf{E}\\)、\\(\\mathbf{H}\\) 的匹配留到 <a href="/litho/fresnel-coefficients">菲涅尔反射与透射</a>。</p><p>电场与磁场耦合成横电磁波，但无源均匀区里每个 Cartesian 分量仍满足标量波动方程。这是后课大量用标量 \\(U\\) 处理衍射的许可证——许可证有边界，在本课程末课才收。矢量偏振在掩模边缘与多层膜处必须请回来，那是后课，不是本课的起点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理色散、吸收与导电损耗：实 \\(\\varepsilon\\)、\\(\\mu\\) 给出实波速。金属趋肤深度、EUV 多层的强吸收，是材料缺口。也不展开边界条件：反射透射系数不在本课推导。几何光学的光线是短波极限，本课尚未引入透镜。</p><p>均匀假设在纳米图形边缘会破。特征与波长可比时必须回到波动，不能只画光线——那是 <a href="/litho/scalar-diffraction-bound">标量衍射的适用边界</a> 的题目。下一课 <a href="/litho/plane-wave-k">平面波与波矢</a> 只问亥姆霍兹的特解长什么样。</p><p>后课默认：无源均匀介质里光满足波动方程；时谐场用 \\(e^{-i\\omega t}\\)，波数 \\(k=\\omega/v\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光刻栏从麦克斯韦方程在无源均匀介质里推出波动方程开始，不从机台或分辨公式开始。</li><li>波速 \\(v=1/\\sqrt{\\mu\\varepsilon}\\)；时谐场满足亥姆霍兹方程，\\(k=\\omega/v\\)。</li><li>后课默认已读完本课；界面、偏振、透镜与衍射都建立在这条链上。</li><li>光学课只铺到标量衍射边界；单色波与光程由后一课程再钉。</li><li>出处：Jackson, <em>Classical Electrodynamics</em>；Born &amp; Wolf, <em>Principles of Optics</em> 第 1 章。</li></ul>',9))])}const v=o(d,[["render",f]]);export{B as __pageData,v as default};
